/**
 * Studio types for Natural Language Prompt-to-Agent authoring, simulation, and installation.
 */

import type { ToolDefinition } from './tools.ts';
import type { SinkAction } from './sinks.ts';
import type { LogEntry, AgentContext } from './context.ts';

/**
 * Serializable specification of an agent generated by Prompt-to-Agent Studio.
 */
export interface AgentManifest {
  readonly name: string;
  readonly version: string;
  readonly description: string;
  readonly prompt: string;
  readonly triggers: readonly AgentTrigger[];
  readonly tools: readonly string[];
  readonly capabilities: readonly AgentCapabilityRequest[];
  readonly sinks: readonly AgentSinkConfig[];
  readonly memoryScope: 'org' | 'repo' | 'both';
  readonly lifecycleHooks?: {
    readonly beforeRun?: boolean;
    readonly afterRun?: boolean;
  };
  readonly metadata?: Record<string, unknown>;
}

export interface AgentTrigger {
  readonly event: string;
  readonly filter?: Record<string, unknown>;
}

export interface AgentCapabilityRequest {
  readonly service: string;
  readonly action: string;
}

export interface AgentSinkConfig {
  readonly type: string;
  readonly config?: Record<string, unknown>;
}

/**
 * Control and data plane context provided to the compiler for grounded agent synthesis.
 */
export interface StudioContext {
  readonly availableTools?: readonly ToolDefinition[];
  readonly availableSinks?: readonly string[];
  readonly availablePermissions?: readonly AgentCapabilityRequest[];
  readonly repoContext?: {
    readonly owner: string;
    readonly repo: string;
  };
  readonly memoryKeys?: readonly string[];
}

/**
 * Custom synthesis function (e.g. LLM-backed) to generate or refine an AgentManifest.
 */
export type AgentSynthesisFn = (
  prompt: string,
  context: StudioContext
) => Promise<Partial<AgentManifest>>;

/**
 * Input request for simulating an agent run inside the Studio test harness.
 */
export interface SimulationRequest {
  readonly manifest: AgentManifest;
  readonly event?: Record<string, unknown>;
  readonly promptInput?: string;
  readonly mockToolResponses?: Record<string, unknown>;
  readonly mockToolInputs?: Record<string, unknown>;
}

export interface SimulatedToolCall {
  readonly tool: string;
  readonly params: Record<string, unknown>;
  readonly result: unknown;
  readonly durationMs: number;
}

export interface SimulatedMemoryMutation {
  readonly scope: 'org' | 'repo';
  readonly key: string;
  readonly operation: 'set' | 'delete';
  readonly value?: unknown;
}

export interface SimulatedPermissionCheck {
  readonly service: string;
  readonly action: string;
  readonly allowed: boolean;
}

export interface SimulationContext {
  readonly ctx: AgentContext;
  readonly invokeTool: (name: string, params: Record<string, unknown>) => Promise<unknown>;
}

/**
 * Detailed trace output from an agent simulation run.
 */
export interface SimulationResult {
  readonly runId: string;
  readonly status: 'completed' | 'failed' | 'denied';
  readonly logs: readonly LogEntry[];
  readonly toolCalls: readonly SimulatedToolCall[];
  readonly sinkActions: readonly SinkAction[];
  readonly memoryMutations: readonly SimulatedMemoryMutation[];
  readonly permissionChecks: readonly SimulatedPermissionCheck[];
  readonly output?: unknown;
  readonly error?: string;
  readonly durationMs: number;
}
